import java.util.Scanner;

public class Main {
    static class UnionFind {
        int[] parent;
        int[] size;

        void setup(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; ++i) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int findRoot(int x) {
            if (parent[x] != x) {
                parent[x] = findRoot(parent[x]);
            }
            return parent[x];
        }

        void connect(int a, int b) {
            a = findRoot(a);
            b = findRoot(b);
            if (a != b) {
                if (size[a] < size[b]) {
                    int temp = a;
                    a = b;
                    b = temp;
                }
                parent[b] = a;
                size[a] += size[b];
            }
        }
    }

    static long powerModulo(long base, int exponent, int modulus) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exponent >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        final int MOD = 1000000007;

        if (k == 0) {
            System.out.println(powerModulo(n, n - 1, MOD));
            sc.close();
            return;
        }

        UnionFind uf = new UnionFind();
        uf.setup(n);
        for (int i = 0; i < n; ++i) {
            uf.connect(i, (int)((long)i * k % n));
        }

        long total = 1;
        for (int i = 0; i < n; ++i) {
            if (uf.findRoot(i) != i) continue;
            long t = powerModulo(k, uf.size[uf.findRoot(i)], n);
            if (t == 1) {
                total = (total * n) % MOD;
            }
        }
        System.out.println(total);
        sc.close();
    }
}
